"""Stamp asset URLs and generate an atomic, integrity-checked Mini App cache worker."""
import hashlib
import json
import re
from pathlib import Path

PROJECT = Path(__file__).resolve().parents[1]
ROOT = PROJECT / 'miniapp' if (PROJECT / 'miniapp/index.html').is_file() else PROJECT
HTML_PAGES = [name for name in ('index.html', 'legacy.html') if (ROOT / name).is_file()]

raw_pages = {}
for name in HTML_PAGES:
    html_text = (ROOT / name).read_text(encoding='utf-8')
    html_text = re.sub(r'(<meta name="golka-cache-version" content=")[^"]*', r'\g<1>BUILD', html_text)
    html_text = re.sub(r'((?:src|href)="[^":]+\.(?:js|css)\?v=)[^"]+', r'\g<1>BUILD', html_text)
    raw_pages[name] = html_text

assets = sorted(p for p in ROOT.iterdir() if p.suffix in {'.js', '.css'} and p.name != 'sw.js')
build = hashlib.sha256(
    Path(__file__).read_bytes()
    + b''.join(name.encode() + raw_pages[name].encode('utf-8') for name in HTML_PAGES)
    + b''.join(p.name.encode() + p.read_bytes() for p in assets)
).hexdigest()[:16]

manifest = {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in assets}
for name in HTML_PAGES:
    stamped = raw_pages[name].replace('content="BUILD"', 'content="' + build + '"').replace('?v=BUILD', '?v=' + build)
    (ROOT / name).write_text(stamped, encoding='utf-8', newline='\n')
    manifest[name] = hashlib.sha256(stamped.encode('utf-8')).hexdigest()

worker = '''/* Generated by tools/build_miniapp_cache.py. Never intercept authenticated APIs or advertising events. */
'use strict';
const VERSION=__VERSION__,ASSETS=__MANIFEST__,PREFIX='golka-static-',CACHE=PREFIX+VERSION;
const base=new URL('./',self.location.href);
const assetURL=name=>new URL((name==='index.html'||name==='legacy.html')?name:name+'?v='+VERSION,base).href;
const digest=async data=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data)),v=>v.toString(16).padStart(2,'0')).join('');
async function verified(name){const url=assetURL(name);let r=await fetch(url,{cache:'force-cache',credentials:'omit'});if(!r.ok||await digest(await r.clone().arrayBuffer())!==ASSETS[name])r=await fetch(url,{cache:'reload',credentials:'omit'});if(!r.ok||await digest(await r.clone().arrayBuffer())!==ASSETS[name])throw Error('Incomplete asset deployment');return r}
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);try{await Promise.all(Object.keys(ASSETS).map(async name=>{const response=await verified(name);await cache.put(assetURL(name),response)}))}catch(error){await caches.delete(CACHE);throw error}await self.skipWaiting()})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{const keys=(await caches.keys()).filter(k=>k.startsWith(PREFIX));const previous=keys.filter(k=>k!==CACHE).slice(-1);await Promise.all(keys.filter(k=>k!==CACHE&&!previous.includes(k)).map(k=>caches.delete(k)));await self.clients.claim()})()));
async function navigation(request,page){const key=Object.hasOwn(ASSETS,page)?page:'index.html';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),2500);try{const response=await fetch(request,{cache:'no-cache',signal:controller.signal});if(response.ok){if(await digest(await response.clone().arrayBuffer())===ASSETS[key]){const cache=await caches.open(CACHE);await cache.put(assetURL(key),response.clone())}return response}const saved=await caches.match(assetURL(key));return saved||response}catch(error){const saved=await caches.match(assetURL(key));if(saved)return saved;throw error}finally{clearTimeout(timer)}}
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==base.origin||request.headers.has('Authorization')||!url.pathname.startsWith(base.pathname))return;const name=url.pathname.slice(base.pathname.length);if(request.mode==='navigate'&&(name===''||name==='index.html'||name==='legacy.html')){event.respondWith(navigation(request,name||'index.html'));return}if(!Object.hasOwn(ASSETS,name)||name==='index.html'||name==='legacy.html')return;event.respondWith((async()=>{const cached=await caches.match(request);if(cached)return cached;if(url.searchParams.get('v')===VERSION){const response=await verified(name);const cache=await caches.open(CACHE);await cache.put(assetURL(name),response.clone());return response}return fetch(request)})())});
'''.replace('__VERSION__', json.dumps(build)).replace('__MANIFEST__', json.dumps(manifest, separators=(',', ':')))

(ROOT / 'sw.js').write_text(worker, encoding='utf-8', newline='\n')
print(json.dumps({'build': build, 'assets': len(manifest), 'bytes': sum((ROOT / n).stat().st_size for n in manifest)}))
